// C interface to Anki's Rust backend. Every call except open/close goes
// through anki_run_method: a service index, a method index and a serialized
// protobuf request in; a serialized response (or anki.backend.BackendError) out.
// The indices come from upstream's proto_gen, and the Swift wrappers that use
// them are generated by swiftgen/.

#ifndef ANKI_BRIDGE_H
#define ANKI_BRIDGE_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

typedef struct AnkiBackend AnkiBackend;

// Bytes owned by Rust. Release with anki_free_buffer.
typedef struct {
    uint8_t *ptr;
    size_t len;
    size_t cap;
} AnkiBuffer;

// `init` is a serialized anki.backend.BackendInit. On failure returns NULL and
// fills `error` with a UTF-8 message.
AnkiBackend *anki_open_backend(const uint8_t *init, size_t init_len, AnkiBuffer *error);

void anki_close_backend(AnkiBackend *backend);

// Returns true and fills `out` with the response on success; returns false and
// fills `out` with a serialized anki.backend.BackendError on failure.
// Safe to call from any thread.
bool anki_run_method(const AnkiBackend *backend, uint32_t service, uint32_t method,
                     const uint8_t *input, size_t input_len, AnkiBuffer *out);

// Raw SQL against the open collection, same JSON protocol as the Python
// bridge's db_command. Same return convention as anki_run_method.
bool anki_run_db_command(const AnkiBackend *backend, const uint8_t *input, size_t input_len,
                         AnkiBuffer *out);

// `path` may be NULL to log to stderr only.
bool anki_init_logging(const char *path);

void anki_free_buffer(AnkiBuffer buffer);

#endif
